/*
 * headless_thread_verbs.c - Thread processor verb implementations
 *
 * Originally generated by tools/kernelverbs_parser/generate_processor_stubs.py
 * but now contains production implementations. DO NOT regenerate.
 *
 * Implementation pattern:
 * - Directly delegates to cooperative threading functions in process.c
 * - Thread ID parameters require lookup via getprocessthread() before delegation
 * - Error handling validates thread handles with goodthread()
 * - Allows thread.* verbs to work in headless mode
 *
 * To add new thread verbs: Add case statements to thread_valueproc() following
 * the established pattern (extract params → lookup thread → delegate).
 *
 * See docs/verb_implementation_status.md for implementation status.
 */

#include "frontier.h"
#include "standard.h"

#include "memory.h"
#include "strings.h"
#include "lang.h"
#include "langinternal.h"
#include "tablestructure.h"
#include "tableverbs.h"
#include "process.h"
#include "shellthreads.h"
#include "logging.h"

/* Constant for tick-to-second conversion (classic Mac ticks = 60/sec) */
#define TICKS_PER_SECOND 60

/* Token enum for all verbs in the thread processor.
 * Naming convention: thrv_<verbname> for thread verbs */
enum {
    thrv_exists = 0,
    thrv_evaluate = 1,
    thrv_callscript = 2,
    thrv_getcurrentid = 3,
    thrv_getcount = 4,
    thrv_getnthid = 5,
    thrv_sleep = 6,
    thrv_sleepfor = 7,
    thrv_sleepticks = 8,
    thrv_issleeping = 9,
    thrv_wake = 10,
    thrv_kill = 11,
    thrv_gettimeslice = 12,
    thrv_settimeslice = 13,
    thrv_getdefaulttimeslice = 14,
    thrv_setdefaulttimeslice = 15,
    thrv_getstats = 16
};

static boolean thread_valueproc(short token, hdltreenode hparam1,
                                     tyvaluerecord *vreturned,
                                     bigstring bserror) {
    switch(token) {
        case thrv_exists: {
            /* Verb #0: thread.exists - Check if thread exists */
            long id;

            if (!langcheckparamcount(hparam1, 1))
                return false;

            flnextparamislast = true;
            if (!getlongvalue(hparam1, 1, &id))
                return false;

            return setbooleanvalue(getprocessthread(id) != nil, vreturned);
        }
        case thrv_evaluate: {
            /* Verb #1: thread.evaluate - Evaluate code string in new thread */
            bigstring bscode;

            if (!langcheckparamcount(hparam1, 1))
                return false;

            flnextparamislast = true;
            if (!getstringvalue(hparam1, 1, bscode))
                return false;

            return thread_evaluate_kernel(bscode, vreturned);
        }
        case thrv_callscript: {
            /* Verb #2: thread.callscript - Call script in new thread */
            bigstring bsscriptname;
            tyvaluerecord vparams;
            hdlhashtable hcontext = nil;

            /* Get script name (required) */
            if (!getstringvalue(hparam1, 1, bsscriptname))
                return false;

            /* Get parameters (required) */
            if (!getparamvalue(hparam1, 2, &vparams))
                return false;

            /* Get optional context table (3rd param) */
            if (langgetparamcount(hparam1) > 2) {
                flnextparamislast = true;

                if (!gettablevalue(hparam1, 3, &hcontext))
                    return false;
            } else {
                flnextparamislast = true;
            }

            return thread_callscript_kernel(bsscriptname, vparams, hcontext, vreturned);
        }
        case thrv_getcurrentid: {
            /* Verb #3: thread.getcurrentid - Get current thread ID */
            hdlprocessthread hthread;

            if (!langcheckparamcount(hparam1, 0))
                return false;

            hthread = getcurrentthread();
            if (hthread == nil)
                return setlongvalue(0, vreturned);
            return setlongvalue(getthreadid(hthread), vreturned);
        }
        case thrv_getcount: {
            /* Verb #4: thread.getcount - Get count of active threads */
            if (!langcheckparamcount(hparam1, 0))
                return false;

            return setlongvalue(processthreadcount(), vreturned);
        }
        case thrv_getnthid: {
            /* Verb #5: thread.getnthid - Get Nth thread ID */
            short n;
            hdlprocessthread hthread;

            if (!langcheckparamcount(hparam1, 1))
                return false;

            flnextparamislast = true;
            if (!getintvalue(hparam1, 1, &n))
                return false;

            hthread = nthprocessthread(n);
            if (hthread == nil)
                return setlongvalue(0, vreturned);
            return setlongvalue(getthreadid(hthread), vreturned);
        }
        case thrv_sleep:
            /* Verb #6: thread.sleep - not yet implemented */
            log_warn(LOG_COMP_LANG, "thread.sleep not yet implemented");
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case thrv_sleepfor: {
            /* Verb #7: thread.sleepfor - Sleep for N seconds (60-tick seconds) */
            long seconds;
            boolean fl;

            if (!langcheckparamcount(hparam1, 1))
                return false;

            flnextparamislast = true;
            if (!getlongvalue(hparam1, 1, &seconds))
                return false;

            fl = processsleep(getcurrentthread(), seconds * TICKS_PER_SECOND);
            return setbooleanvalue(fl, vreturned);
        }
        case thrv_sleepticks: {
            /* Verb #8: thread.sleepticks - Sleep for N ticks */
            long ticks;
            boolean fl;

            if (!langcheckparamcount(hparam1, 1))
                return false;

            flnextparamislast = true;
            if (!getlongvalue(hparam1, 1, &ticks))
                return false;

            fl = processsleep(getcurrentthread(), ticks);
            return setbooleanvalue(fl, vreturned);
        }
        case thrv_issleeping: {
            /* Verb #9: thread.issleeping - Check if thread is sleeping */
            long id;
            hdlprocessthread hthread;

            if (!langcheckparamcount(hparam1, 1))
                return false;

            flnextparamislast = true;
            if (!getlongvalue(hparam1, 1, &id))
                return false;

            hthread = getprocessthread(id);
            if (hthread == nil)
                return false;

            return setbooleanvalue(processissleeping(hthread), vreturned);
        }
        case thrv_wake: {
            /* Verb #10: thread.wake - Wake sleeping thread */
            long id;
            hdlprocessthread hthread;

            if (!langcheckparamcount(hparam1, 1))
                return false;

            flnextparamislast = true;
            if (!getlongvalue(hparam1, 1, &id))
                return false;

            hthread = getprocessthread(id);
            if (hthread == nil)
                return false;

            return setbooleanvalue(wakeprocessthread(hthread), vreturned);
        }
        case thrv_kill: {
            /* Verb #11: thread.kill - Terminate thread */
            long id;
            hdlprocessthread hthread;

            if (!langcheckparamcount(hparam1, 1))
                return false;

            flnextparamislast = true;
            if (!getlongvalue(hparam1, 1, &id))
                return false;

            hthread = getprocessthread(id);
            if (hthread == nil)
                return false;

            return setbooleanvalue(killprocessthread(hthread), vreturned);
        }
        case thrv_gettimeslice:
            /* Verb #12: thread.gettimeslice - not yet implemented */
            log_warn(LOG_COMP_LANG, "thread.gettimeslice not yet implemented");
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case thrv_settimeslice:
            /* Verb #13: thread.settimeslice - not yet implemented */
            log_warn(LOG_COMP_LANG, "thread.settimeslice not yet implemented");
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case thrv_getdefaulttimeslice:
            /* Verb #14: thread.getdefaulttimeslice - not yet implemented */
            log_warn(LOG_COMP_LANG, "thread.getdefaulttimeslice not yet implemented");
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case thrv_setdefaulttimeslice:
            /* Verb #15: thread.setdefaulttimeslice - not yet implemented */
            log_warn(LOG_COMP_LANG, "thread.setdefaulttimeslice not yet implemented");
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        case thrv_getstats:
            /* Verb #16: thread.getstats - not yet implemented */
            log_warn(LOG_COMP_LANG, "thread.getstats not yet implemented");
            if (bserror) copystring(BIGSTRING("\pnot implemented"), bserror);
            return false;
        default:
            return false;
    }
}

boolean threadinitverbs(void) {
    hdlhashtable htable = nil;
    bigstring bsname;

    copystring(BIGSTRING("\pthread"), bsname);

    if (!newfunctionprocessor(bsname, &thread_valueproc, false, &htable))
        return false;

    pushhashtable(htable);

    #define ADD_VERB(name, tok) do { \
        bigstring bs; \
        copystring(name, bs); \
        if (!langaddkeyword(bs, tok)) { \
            pophashtable(); \
            return false; \
        } \
    } while(0)

    ADD_VERB(BIGSTRING("\pexists"), thrv_exists);
    ADD_VERB(BIGSTRING("\pevaluate"), thrv_evaluate);
    ADD_VERB(BIGSTRING("\pcallscript"), thrv_callscript);
    ADD_VERB(BIGSTRING("\pgetcurrentid"), thrv_getcurrentid);
    ADD_VERB(BIGSTRING("\pgetcount"), thrv_getcount);
    ADD_VERB(BIGSTRING("\pgetnthid"), thrv_getnthid);
    ADD_VERB(BIGSTRING("\psleep"), thrv_sleep);
    ADD_VERB(BIGSTRING("\psleepfor"), thrv_sleepfor);
    ADD_VERB(BIGSTRING("\psleepticks"), thrv_sleepticks);
    ADD_VERB(BIGSTRING("\pissleeping"), thrv_issleeping);
    ADD_VERB(BIGSTRING("\pwake"), thrv_wake);
    ADD_VERB(BIGSTRING("\pkill"), thrv_kill);
    ADD_VERB(BIGSTRING("\pgettimeslice"), thrv_gettimeslice);
    ADD_VERB(BIGSTRING("\psettimeslice"), thrv_settimeslice);
    ADD_VERB(BIGSTRING("\pgetdefaulttimeslice"), thrv_getdefaulttimeslice);
    ADD_VERB(BIGSTRING("\psetdefaulttimeslice"), thrv_setdefaulttimeslice);
    ADD_VERB(BIGSTRING("\pgetstats"), thrv_getstats);

    #undef ADD_VERB

    pophashtable();
    return true;
}
